// Secure version of app.js with improved error handling and input validation
// Focus on security best practices

const express = require('express');
const helmet = require('helmet'); // Security headers
const cors = require('cors'); // CORS protection
const rateLimit = require('express-rate-limit'); // Rate limiting
const { body, query, validationResult } = require('express-validator'); // Input validation
const app = express();

// Security Middleware Setup
// =========================

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Configure CORS properly
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: false
});
// Apply to all requests
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request ID for logging and tracing
app.use((req, res, next) => {
  req.id = require('crypto').randomUUID();
  next();
});

// Error Handling Middleware
// =========================

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error [${req.id}]:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  const statusCode = err.statusCode || 500;
  const response = {
    error: 'Internal Server Error',
    requestId: req.id,
    timestamp: new Date().toISOString()
  };

  // Only include details in development
  if (process.env.NODE_ENV === 'development') {
    response.message = err.message;
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// Input Validation Error Handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Error',
      requestId: req.id,
      timestamp: new Date().toISOString(),
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Custom Error Classes
class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.name = this.constructor.name;
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

class NotFoundError extends AppError {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

// Utility Functions
// =================

const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    // Basic XSS protection (for simple cases - use a library like DOMPurify for HTML)
    return input
      .replace(/[<>"']/g, '') // Remove dangerous HTML characters
      .trim();
  }
  return input;
};

const validateEmail = (email) => {
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email);
};

// Routes with Enhanced Security
// =============================

// Health check with input validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      requestId: req.id
    });
  } catch (error) {
    next(new AppError('Health check failed', 503));
  }
});

// Users endpoint with proper validation
app.get('/users', 
  [
    // Query parameter validation
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
    query('search').optional().isLength({ min: 1, max: 50 }).withMessage('Search term must be 1-50 characters'),
    handleValidationErrors
  ],
  async (req, res, next) => {
    try {
      // Get and sanitize query parameters
      let { limit = 10, offset = 0, search = '' } = req.query;

      // Type conversion with validation
      limit = parseInt(limit);
      offset = parseInt(offset);
      search = sanitizeInput(search);

      // Use parameterized queries for database operations
      // This prevents SQL injection
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter based on search if provided
      const filteredUsers = search 
        ? users.filter(user => 
            user.name.toLowerCase().includes(search.toLowerCase()) ||
            user.email.toLowerCase().includes(search.toLowerCase())
          )
        : users;

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          total: filteredUsers.length,
          limit,
          offset,
          hasMore: offset + limit < filteredUsers.length
        },
        requestId: req.id
      });
    } catch (error) {
      next(new AppError('Failed to fetch users', 500));
    }
  }
);

// Example POST endpoint with comprehensive validation
app.post('/users',
  [
    // Body validation
    body('name').notEmpty().trim().escape().withMessage('Name is required'),
    body('email').notEmpty().isEmail().normalizeEmail().withMessage('Valid email is required'),
    body('age').optional().isInt({ min: 18, max: 100 }).withMessage('Age must be between 18 and 100'),
    handleValidationErrors
  ],
  async (req, res, next) => {
    try {
      const { name, email, age } = req.body;

      // Additional business logic validation
      if (!validateEmail(email)) {
        throw new ValidationError('Invalid email format');
      }

      // In a real application, this would interact with a database
      // Using parameterized queries to prevent SQL injection
      const newUser = {
        id: Date.now(), // In real app, use database-generated ID
        name: sanitizeInput(name),
        email: sanitizeInput(email),
        age: age ? parseInt(age) : null,
        createdAt: new Date().toISOString()
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
        requestId: req.id
      });
    } catch (error) {
      next(error);
    }
  }
);

// Protected route example (requires authentication)
app.get('/profile',
  // Authentication middleware would go here
  async (req, res, next) => {
    try {
      // Check authentication
      const authHeader = req.headers.authorization;
      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        throw new AppError('Authentication required', 401);
      }

      // Verify token (in real app)
      const token = authHeader.substring(7);
      // const user = verifyToken(token);

      res.json({
        message: 'Authenticated user profile',
        requestId: req.id
      });
    } catch (error) {
      next(error);
    }
  }
);

// 404 handler - must be last route
app.use('*', (req, res, next) => {
  next(new NotFoundError(`Route ${req.originalUrl} not found`));
});

// Unhandled Promise Rejection and Exception handlers
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to exit the process
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);
  // Close database connections, etc.
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

// Minimal upgrade to app.js with basic security improvements
// Start with these improvements, then gradually add more

const express = require('express');
const app = express();

// 1. BASIC SECURITY HEADERS (No external dependencies)
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// 2. BASIC INPUT SANITIZATION
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return input
    .replace(/[<>"']/g, '') // Remove dangerous HTML characters
    .trim()
    .substring(0, 100); // Limit length
};

// 3. ERROR HANDLING MIDDLEWARE
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose stack traces in production
  const response = {
    error: 'Something went wrong',
    timestamp: new Date().toISOString()
  };

  // Customize based on error type
  if (err.statusCode) {
    res.status(err.statusCode).json(response);
  } else {
    res.status(500).json(response);
  }
});

// 4. RATE LIMITING SIMULATION (Basic version)
const requestCounts = {};
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100;

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  if (!requestCounts[ip]) {
    requestCounts[ip] = [];
  }

  // Remove old requests
  requestCounts[ip] = requestCounts[ip].filter(time => now - time < RATE_LIMIT_WINDOW);

  // Check rate limit
  if (requestCounts[ip].length >= RATE_LIMIT_MAX) {
    return res.status(429).json({
      error: 'Too many requests, please try again later',
      retryAfter: Math.ceil((requestCounts[ip][0] + RATE_LIMIT_WINDOW - now) / 1000)
    });
  }

  // Add current request
  requestCounts[ip].push(now);
  next();
});

// HEALTH CHECK WITH VALIDATION
app.get('/health', (req, res, next) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    next(error);
  }
});

// USERS ENDPOINT WITH INPUT VALIDATION
app.get('/users', (req, res, next) => {
  try {
    // Validate and sanitize query parameters
    let { limit = 10, search = '' } = req.query;

    // Convert limit to number with bounds
    limit = parseInt(limit);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      limit = 10;
    }

    // Sanitize search input
    search = sanitizeInput(search);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter (example)
    const filteredUsers = search 
      ? users.filter(user => 
          user.name.toLowerCase().includes(search.toLowerCase()))
      : users;

    // Apply limit
    const result = filteredUsers.slice(0, limit);

    res.json({
      data: result,
      meta: {
        total: filteredUsers.length,
        limit: limit,
        search: search || null
      }
    });
  } catch (error) {
    next(error);
  }
});

// 404 HANDLER
app.use('*', (req, res, next) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl
  });
});

// START SERVER
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);

  // Basic security warning
  if (process.env.NODE_ENV === 'production') {
    console.warn('\n⚠️  SECURITY WARNINGS:');
    console.warn('   - Consider using helmet.js for security headers');
    console.warn('   - Add proper CORS configuration');
    console.warn('   - Implement proper authentication');
    console.warn('   - Use environment variables for configuration\n');
  }
});

module.exports = app;

