// Enhanced application with comprehensive security measures
// This version includes proper error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const Joi = require('joi'); // For input validation
const morgan = require('morgan'); // For request logging

const app = express();

// ======================
// SECURITY MIDDLEWARE
// ======================

// 1. Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Enable CORS with secure configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com']
    : ['http://localhost:3000', 'http://localhost:8080'],
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter); // Apply to all API routes

// 4. Request logging (use 'combined' for production, 'dev' for development)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 5. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ======================
// INPUT VALIDATION SCHEMAS
// ======================

const userIdSchema = Joi.object({
  id: Joi.number().integer().min(1).max(999999).required()
});

const userQuerySchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10),
  sort: Joi.string().valid('name', 'email', 'id').default('id'),
  order: Joi.string().valid('asc', 'desc').default('asc')
});

// ======================
// ERROR HANDLING MIDDLEWARE
// ======================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Default error status
  const statusCode = error.statusCode || 500;

  // Don't expose internal errors in production
  const message = process.env.NODE_ENV === 'production' && statusCode === 500
    ? 'Internal Server Error'
    : error.message || 'Something went wrong';

  res.status(statusCode).json({
    error: error.name || 'Error',
    message: message,
    timestamp: new Date().toISOString(),
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack })
  });
});

// ======================
// ENHANCED ROUTES WITH VALIDATION
// ======================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    uptime: process.uptime()
  });
});

// Get users with query parameter validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const { error, value } = userQuerySchema.validate(req.query);
    if (error) {
      const validationError = new Error(`Validation error: ${error.details[0].message}`);
      validationError.statusCode = 400;
      validationError.name = 'ValidationError';
      throw validationError;
    }

    const { page, limit, sort, order } = value;

    // In a real application, you would fetch from database with pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simulate pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    // Sort users
    paginatedUsers.sort((a, b) => {
      if (order === 'asc') {
        return a[sort] > b[sort] ? 1 : -1;
      } else {
        return a[sort] < b[sort] ? 1 : -1;
      }
    });

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    next(error);
  }
});

// Get single user with ID validation
app.get('/users/:id', (req, res, next) => {
  try {
    // Validate path parameter
    const { error, value } = userIdSchema.validate({ id: req.params.id });
    if (error) {
      const validationError = new Error(`Invalid user ID: ${error.details[0].message}`);
      validationError.statusCode = 400;
      validationError.name = 'ValidationError';
      throw validationError;
    }

    const userId = value.id;
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);
    if (!user) {
      const notFoundError = new Error(`User with ID ${userId} not found`);
      notFoundError.statusCode = 404;
      notFoundError.name = 'NotFoundError';
      throw notFoundError;
    }

    res.json({ data: user });
  } catch (error) {
    next(error);
  }
});

// ======================
// SECURITY HEADERS ROUTE (for verification)
// ======================

app.get('/security-headers', (req, res) => {
  res.json({
    message: 'Security headers are configured via Helmet middleware',
    headers: {
      'Content-Security-Policy': 'active',
      'X-Frame-Options': 'active', 
      'X-Content-Type-Options': 'active',
      'Referrer-Policy': 'active',
      'Strict-Transport-Security': 'active'
    }
  });
});

// ======================
// SERVER STARTUP
// ======================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Validate environment variables on startup
function validateEnvironment() {
  const requiredEnvVars = ['NODE_ENV'];
  const missing = requiredEnvVars.filter(env => !process.env[env]);

  if (missing.length > 0 && process.env.NODE_ENV === 'production') {
    console.error(`Missing required environment variables: ${missing.join(', ')}`);
    process.exit(1);
  }
}

validateEnvironment();

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

function gracefulShutdown() {
  console.log('Received shutdown signal, closing server...');

  server.close((err) => {
    if (err) {
      console.error('Error during shutdown:', err);
      process.exit(1);
    }

    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
}

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown();
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to log to a monitoring service
});

module.exports = app;

