  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// Input validation middleware
const validateUserQuery = (req, res, next) => {
  const { limit, offset } = req.query;

  // Validate numeric parameters
  if (limit && !/^\d+$/.test(limit)) {
    return res.status(400).json({ 
      error: 'Invalid limit parameter. Must be a positive integer.' 
    });
  }

  if (offset && !/^\d+$/.test(offset)) {
    return res.status(400).json({ 
      error: 'Invalid offset parameter. Must be a positive integer.' 
    });
  }

  // Enforce reasonable limits
  if (limit && parseInt(limit) > 100) {
    return res.status(400).json({ 
      error: 'Limit cannot exceed 100.' 
    });
  }

  next();
};

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error occurred:', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Don't expose internal error details in production
  const isProduction = process.env.NODE_ENV === 'production';
  const errorResponse = {
    error: 'Internal Server Error',
    message: isProduction ? 'Something went wrong' : err.message,
    ...(!isProduction && { stack: err.stack }),
  };

  res.status(err.status || 500).json(errorResponse);
};

// Request logging middleware
const requestLogger = (req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.originalUrl} ${res.statusCode} ${duration}ms`);
  });

  next();
};

app.use(requestLogger);

// Basic routes with improved error handling
app.get('/health', (req, res) => {
  try {
    // Add some health check logic
    const healthStatus = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      env: process.env.NODE_ENV || 'development',
    };

    // Remove sensitive data in production
    if (process.env.NODE_ENV === 'production') {
      delete healthStatus.memory;
    }

    res.json(healthStatus);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ 
      status: 'unhealthy', 
      timestamp: new Date().toISOString(),
      error: 'Service temporarily unavailable'
    });
  }
});

// Users endpoint with validation and sanitization
app.get('/users', validateUserQuery, (req, res) => {
  try {
    const { limit = 10, offset = 0 } = req.query;
    const parsedLimit = parseInt(limit);
    const parsedOffset = parseInt(offset);

    // Sample user data (in production, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    // Sanitize output (remove or mask sensitive data if needed)
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      // In production, consider masking email or removing completely
      email: user.email.replace(/(?<=.).(?=.*@)/g, '*'), // Basic email masking
    }));

    res.json({
      users: sanitizedUsers,
      pagination: {
        total: allUsers.length,
        limit: parsedLimit,
        offset: parsedOffset,
        hasMore: parsedOffset + parsedLimit < allUsers.length,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    throw error; // Let error handler catch it
  }
});

// User detail endpoint with parameter validation
app.get('/users/:id', (req, res) => {
