if (process.env.NODE_ENV !== 'production') {
  try {
    require('dotenv').config();
    console.log('Environment variables loaded from .env file');
  } catch (error) {
    console.log('No .env file found, using system environment variables');
  }
}

const app = express();

// Basic input validation middleware
app.use((req, res, next) => {
  // Basic security: Prevent common attacks
  // 1. Limit request body size
  if (req.headers['content-length'] > 10000) { // 10KB limit
    return res.status(413).json({ error: 'Request body too large' });
  }

  // 2. Log requests for monitoring
  console.log(`${new Date().toISOString()} ${req.method} ${req.url}`);
  next();
});

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/users', (req, res) => {
  try {
    // Basic input validation for query parameters
    const limit = parseInt(req.query.limit) || 10;
    if (limit > 100 || limit < 1) {
      return res.status(400).json({ error: 'Limit must be between 1 and 100' });
    }

    // Static response with proper headers
    res.set('Content-Type', 'application/json');
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

// 404 error handler
app.use((req, res) => {
  res.status(404).json({ error: `Route not found: ${req.method} ${req.url}` });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);
  const status = error.status || 500;
  const message = process.env.NODE_ENV === 'development' ? error.message : 'Internal server error';
  res.status(status).json({ error: message });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Ensure proper shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

