/**
 * Secure Express Application with Enhanced Error Handling and Input Validation
 * Security Best Practices Implementation
 */

const express = require('express');
const helmet = require('helmet'); // Security headers
const cors = require('cors'); // CORS configuration
const rateLimit = require('express-rate-limit'); // Rate limiting
const { body, validationResult } = require('express-validator'); // Input validation
const winston = require('winston'); // Structured logging
const dotenv = require('dotenv'); // Environment management

// Load environment variables
dotenv.config();

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// 2. CORS configuration (adjust based on your requirements)
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? [/\.yourdomain\.com$/] // Production origins
    : ['http://localhost:3000', 'http://localhost:3001'], // Development origins
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  message: { 
    error: 'Too many requests from this IP, please try again after 15 minutes' 
  }
});
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large JSON payloads
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ==================== LOGGING SETUP ====================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'api-service' },
  transports: [
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    }),
    new winston.transports.File({ 
      filename: 'error.log', 
      level: 'error' 
    }),
    new winston.transports.File({ 
      filename: 'combined.log' 
    })
  ]
});

// Logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });
  next();
});

// ==================== ERROR HANDLING MIDDLEWARES ====================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn({ 
      validationErrors: errors.array(),
      path: req.path,
      ip: req.ip 
    });
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        param: err.param,
        msg: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Global error handler
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  logger.error({
    error: message,
    stack: err.stack,
    statusCode: statusCode,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't expose internal errors in production
  const response = {
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  };

  res.status(statusCode).json(response);
});

// 404 handler
app.use((req, res, next) => {
  logger.warn({ 
    message: 'Route not found', 
    path: req.path, 
    method: req.method,
    ip: req.ip 
  });
  res.status(404).json({ 
    error: `Route ${req.method} ${req.path} not found` 
  });
});

// ==================== ROUTES WITH VALIDATION ====================

// Health check endpoint
app.get('/health', asyncHandler(async (req, res) => {
  const health = {
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    environment: process.env.NODE_ENV || 'development'
  };

  res.json(health);
}));

// Users endpoint with validation
app.get('/users', 
  [
    // Input validation (query parameters)
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    handleValidationErrors
  ],
  asyncHandler(async (req, res) => {
    try {
      // Simulate database call with error handling
      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          createdAt: new Date().toISOString()
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          createdAt: new Date().toISOString()
        },
      ];

      // Sanitize sensitive data (if needed)
      const sanitizedUsers = users.map(user => ({
        id: user.id,
        name: user.name
        // Email could be omitted or masked based on requirements
        // email: maskEmail(user.email)
      }));

      res.json({
        success: true,
        data: sanitizedUsers,
        count: sanitizedUsers.length,
        metadata: {
          timestamp: new Date().toISOString(),
          page: parseInt(req.query.page) || 1,
          limit: parseInt(req.query.limit) || users.length
        }
      });

    } catch (error) {
      logger.error({ 
        error: 'Failed to fetch users', 
        details: error.message,
        path: '/users' 
      });
      throw new Error('Failed to fetch users');
    }
  })
);

// Example: Protected route with authentication
app.get('/protected',
  // Add authentication middleware here
  (req, res, next) => {
    // Authentication logic
    const authHeader = req.headers['authorization'];
    if (!authHeader) {
      const error = new Error('Authentication required');
      error.statusCode = 401;
      throw error;
    }
    next();
  },
  asyncHandler(async (req, res) => {
    res.json({ 
      message: 'Authenticated access granted',
      timestamp: new Date().toISOString()
    });
  })
);

// ==================== SERVER SETUP ====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
  logger.info(`🚀 Server running on http://${HOST}:${PORT}`);
  logger.info(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received. Starting graceful shutdown...');
  server.close(() => {
    logger.info('Server closed. Exiting process.');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received. Starting graceful shutdown...');
  server.close(() => {
    logger.info('Server closed. Exiting process.');
    process.exit(0);
  });
});

// Unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error({ 
    type: 'Unhandled Promise Rejection', 
    reason: reason,
    promise: promise 
  });
  // In production, you might want to exit the process
  // if (process.env.NODE_ENV === 'production') {
  //   process.exit(1);
  // }
});

// Uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error({ 
    type: 'Uncaught Exception', 
    error: error.message,
    stack: error.stack 
  });
  // In production, you might want to exit the process
  // if (process.env.NODE_ENV === 'production') {
  //   process.exit(1);
  // }
});

module.exports = { app, server, logger };

// Test script to verify security improvements

const axios = require('axios');
