// Improved application with comprehensive error handling and security practices
// This implementation includes security best practices and proper input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');

const app = express();

// ============================
// 1. SECURITY MIDDLEWARE SETUP
// ============================

// Set security headers using helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
}));

// Enable CORS with proper configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Request parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Structured logging
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health' // Skip health checks from detailed logging
}));

// ============================
// 2. GLOBAL ERROR HANDLING
// ============================

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    error: err.message,
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack
  });

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: {
      message: isProduction ? 'Internal server error' : err.message,
      ...(isProduction ? {} : { stack: err.stack }),
      timestamp: new Date().toISOString(),
      requestId: req.id || 'unknown'
    }
  });
});

// Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Resource not found',
      path: req.path,
      method: req.method,
      timestamp: new Date().toISOString()
    }
  });
});

// ============================
// 3. VALIDATION UTILITIES
// ============================

const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: {
          message: 'Validation failed',
          details: errors.array().map(err => ({
            param: err.param,
            msg: err.msg,
            location: err.location
          })),
          timestamp: new Date().toISOString()
        }
      });
    }
    next();
  };
};

// Input sanitization utility
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;

  // Remove potentially dangerous characters
  return input
    .replace(/[<>]/g, '') // Remove HTML tags
    .replace(/javascript:/gi, '') // Remove javascript: protocol
    .trim();
};

// ============================
// 4. ROUTES WITH VALIDATION
// ============================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with input validation
app.get('/users', 
  validateRequest([
    body('pageNumber').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('pageSize').optional().isInt({ min: 1, max: 100 }).withMessage('Page size must be between 1 and 100')
  ]),
  asyncHandler(async (req, res) => {
    try {
      // Sanitize and validate query parameters
      const pageNumber = req.query.pageNumber ? 
        parseInt(sanitizeInput(req.query.pageNumber)) : 1;
      const pageSize = req.query.pageSize ? 
        parseInt(sanitizeInput(req.query.pageSize)) : 10;

      // In a real application, this would come from a database
      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          createdAt: '2024-01-01T00:00:00.000Z',
          lastLogin: '2024-06-07T10:30:00.000Z'
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          createdAt: '2024-01-02T00:00:00.000Z',
          lastLogin: '2024-06-06T14:45:00.000Z'
        },
      ];

      // Filter sensitive information based on user role (in a real app)
      const safeUsers = users.map(user => ({
        id: user.id,
        name: user.name,
        // Only include email if the request is authenticated (example logic)
        ...(req.user && req.user.role === 'admin' ? { email: user.email } : {}),
        createdAt: user.createdAt
      }));

      res.json({
        data: safeUsers,
        pagination: {
          page: pageNumber,
          pageSize: pageSize,
          totalItems: users.length,
          totalPages: Math.ceil(users.length / pageSize)
        },
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      // Log the error for monitoring
      console.error('Error in /users endpoint:', {
        error: error.message,
        query: req.query,
        timestamp: new Date().toISOString()
      });

      // Rethrow to be caught by global error handler
      throw error;
    }
  })
);

// ============================
// 5. ENVIRONMENT CONFIGURATION
// ============================

// Load environment variables
require('dotenv').config();

// Configuration validation on startup
const validateConfig = () => {
  const requiredEnvVars = ['NODE_ENV'];

  const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);
  if (missingVars.length > 0) {
    console.error(`Missing required environment variables: ${missingVars.join(', ')}`);
    process.exit(1);
  }
};

// ============================
// 6. SERVER STARTUP
// ============================

const startServer = async () => {
  try {
    validateConfig();

    const PORT = process.env.PORT || 3000;
    const server = app.listen(PORT, () => {
      console.log(`Server is running on port ${PORT}`);
      console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`Health check: http://localhost:${PORT}/health`);
    });

    // Graceful shutdown handling
    const shutdown = (signal) => {
      console.log(`\nReceived ${signal}, shutting down gracefully...`);

      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });

      // Force shutdown after 10 seconds
      setTimeout(() => {
        console.error('Could not close connections in time, forcefully shutting down');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));

    // Handle uncaught exceptions
    process.on('uncaughtException', (error) => {
      console.error('Uncaught Exception:', error);
      shutdown('uncaughtException');
    });

    process.on('unhandledRejection', (reason, promise) => {
      console.error('Unhandled Rejection at:', promise, 'reason:', reason);
      shutdown('unhandledRejection');
    });

  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Start the server if this file is run directly
if (require.main === module) {
  startServer();
}

module.exports = app;

// Simple test file to demonstrate security improvements

const request = require('supertest');
const app = require('./app_improved');

describe('Security and Error Handling Tests', () => {
  describe('GET /health', () => {
    it('should return health check with security headers', async () => {
      const response = await request(app)
        .get('/health')
        .expect('Content-Type', /json/)
        .expect(200);

      // Check security headers
      const headers = response.headers;
      expect(headers['x-content-type-options']).toBe('nosniff');
      expect(headers['x-frame-options']).toBe('DENY');
      expect(headers['x-xss-protection']).toBe('0');

      // Check response body
      expect(response.body).toHaveProperty('status', 'ok');
      expect(response.body).toHaveProperty('timestamp');
    });
  });

  describe('GET /users', () => {
    it('should return users with proper validation', async () => {
      const response = await request(app)
        .get('/users')
        .expect('Content-Type', /json/)
        .expect(200);

      expect(response.body).toHaveProperty('data');
      expect(response.body).toHaveProperty('pagination');
      expect(response.body.data).toBeInstanceOf(Array);
    });

    it('should validate pageNumber parameter', async () => {
      const response = await request(app)
        .get('/users?pageNumber=invalid')
        .expect('Content-Type', /json/)
        .expect(400);

      expect(response.body).toHaveProperty('error');
      expect(response.body.error.message).toBe('Validation failed');
    });

    it('should sanitize input parameters', async () => {
      const response = await request(app)
        .get('/users?pageSize=<script>alert("xss")</script>')
        .expect('Content-Type', /json/)
        .expect(400); // This should fail validation

      expect(response.body).toHaveProperty('error');
    });

    it('should handle valid pagination parameters', async () => {
      const response = await request(app)
        .get('/users?pageNumber=1&pageSize=5')
        .expect('Content-Type', /json/)
        .expect(200);

      expect(response.body.pagination).toEqual({
        page: 1,
        pageSize: 5,
        totalItems: 2,
        totalPages: 1
      });
    });
  });

  describe('Error Handling', () => {
    it('should handle 404 errors gracefully', async () => {
      const response = await request(app)
        .get('/nonexistent')
        .expect('Content-Type', /json/)
        .expect(404);

      expect(response.body).toHaveProperty('error');
      expect(response.body.error.message).toBe('Resource not found');
    });

    it('should have rate limiting headers', async () => {
      // Note: In a real test, you'd need to mock the rate limiter
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers).toHaveProperty('ratelimit-limit');
      expect(response.headers).toHaveProperty('ratelimit-remaining');
    });
  });

  describe('CORS', () => {
    it('should include CORS headers', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['access-control-allow-origin']).toBeDefined();
      expect(response.headers['access-control-allow-methods']).toBeDefined();
    });
  });
});

// Note: This test file requires Jest and Supertest to run
// Run with: npm test or npx jest test_app.js

