// Improved Express application with enhanced security, error handling, and input validation
const express = require('express');
const helmet = require('helmet'); // Security headers
const cors = require('cors'); // CORS protection
const rateLimit = require('express-rate-limit'); // Rate limiting
const expressSanitizer = require('express-sanitizer'); // Input sanitization
const Joi = require('joi'); // Input validation

// Initialize Express app
const app = express();

// =========================================
// SECURITY MIDDLEWARE
// =========================================

// 1. Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Configure CORS - restrict origins in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// 3. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use('/api/', limiter);

// 4. Parse JSON and URL-encoded data
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Input sanitization middleware
app.use(expressSanitizer());

// =========================================
// ENVIRONMENT VALIDATION
// =========================================

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
if (process.env.NODE_ENV === 'production') {
  requiredEnvVars.push('PORT', 'DATABASE_URL');
}

const missingEnvVars = requiredEnvVars.filter(env => !process.env[env]);
if (missingEnvVars.length > 0) {
  console.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

// =========================================
// LOGGING MIDDLEWARE
// =========================================

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${new Date().toISOString()} - ${req.method} ${req.originalUrl} - ${res.statusCode} - ${duration}ms`);

    // Log security-relevant information
    if (res.statusCode >= 400) {
      console.warn(`Warning: ${res.statusCode} status for ${req.method} ${req.originalUrl} from ${req.ip}`);
    }
  });
  next();
});

// =========================================
// INPUT VALIDATION SCHEMAS
// =========================================

const userQuerySchema = Joi.object({
  limit: Joi.number()
    .integer()
    .min(1)
    .max(100)
    .default(10)
    .description('Number of users to retrieve'),

  offset: Joi.number()
    .integer()
    .min(0)
    .default(0)
    .description('Number of users to skip'),

  sortBy: Joi.string()
    .valid('id', 'name', 'email')
    .default('id')
    .description('Field to sort by'),

  order: Joi.string()
    .valid('asc', 'desc')
    .default('asc')
    .description('Sort order')
});

// =========================================
// ROUTES WITH PROPER VALIDATION
// =========================================

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Users endpoint with input validation
app.get('/users', async (req, res, next) => {
  try {
    // Validate query parameters
    const { error, value } = userQuerySchema.validate(req.query, {
      abortEarly: false,
      stripUnknown: true
    });

    if (error) {
      return res.status(400).json({
        error: 'Validation Error',
        details: error.details.map(detail => ({
          field: detail.path.join('.'),
          message: detail.message.replace(/['"]/g, '')
        }))
      });
    }

    // Sanitize input (already done by middleware, but double-check)
    const sanitizedQuery = {
      limit: Math.min(Math.max(parseInt(value.limit) || 10, 1), 100),
      offset: Math.max(parseInt(value.offset) || 0, 0),
      sortBy: ['id', 'name', 'email'].includes(value.sortBy) ? value.sortBy : 'id',
      order: value.order === 'desc' ? 'desc' : 'asc'
    };

    // Mock database query with parameters
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply sorting (simplified for mock data)
    const sortedUsers = [...mockUsers].sort((a, b) => {
      if (sanitizedQuery.order === 'asc') {
        return a[sanitizedQuery.sortBy] > b[sanitizedQuery.sortBy] ? 1 : -1;
      } else {
        return a[sanitizedQuery.sortBy] < b[sanitizedQuery.sortBy] ? 1 : -1;
      }
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(
      sanitizedQuery.offset,
      sanitizedQuery.offset + sanitizedQuery.limit
    );

    res.json({
      users: paginatedUsers,
      pagination: {
        total: mockUsers.length,
        limit: sanitizedQuery.limit,
        offset: sanitizedQuery.offset,
        hasMore: sanitizedQuery.offset + sanitizedQuery.limit < mockUsers.length
      },
      query: sanitizedQuery
    });

  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// =========================================
// ERROR HANDLING MIDDLEWARE
// =========================================

// 404 Handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Error handler
app.use((error, req, res, next) => {
  console.error('Application Error:', {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.originalUrl,
    ip: req.ip,
    error: error.message,
    stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
  });

  // Determine appropriate status code
  const statusCode = error.status || error.statusCode || 500;

  // Don't leak stack traces in production
  const response = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : error.message,
    requestId: req.id || Date.now().toString(36),
    timestamp: new Date().toISOString()
  };

  // Add validation error details if available
  if (error.name === 'ValidationError') {
    response.error = 'Validation Error';
    response.details = error.details;
  }

  res.status(statusCode).json(response);
});

// =========================================
// GRACEFUL SHUTDOWN HANDLING
// =========================================

const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${process.env.PORT || 3000}`);
});

// Graceful shutdown handlers
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = { app, server };

