// Enhanced Express application with proper error handling and input validation
// Focused on security best practices for the original app.js

const express = require('express');

// =========================================
// CONFIGURATION & ENVIRONMENT VALIDATION
// =========================================

// Validate required configuration
const requiredConfig = {
  PORT: parseInt(process.env.PORT) || 3000,
  NODE_ENV: process.env.NODE_ENV || 'development'
};

// Configuration validation function
const validateConfig = () => {
  const errors = [];

  // Validate PORT
  if (isNaN(requiredConfig.PORT) || requiredConfig.PORT < 1 || requiredConfig.PORT > 65535) {
    errors.push(`Invalid PORT: ${process.env.PORT}. Must be between 1 and 65535.`);
  }

  // Validate NODE_ENV
  if (!['development', 'production', 'test'].includes(requiredConfig.NODE_ENV)) {
    errors.push(`Invalid NODE_ENV: ${requiredConfig.NODE_ENV}. Must be one of: development, production, test.`);
  }

  if (errors.length > 0) {
    console.error('Configuration Errors:');
    errors.forEach(error => console.error(`  - ${error}`));
    console.error('Please check your environment variables.');
    process.exit(1);
  }

  console.log(`Starting server in ${requiredConfig.NODE_ENV} mode on port ${requiredConfig.PORT}`);
};

// Run validation
validateConfig();

// =========================================
// EXPRESS APPLICATION SETUP
// =========================================

const app = express();

// Basic security middleware
app.use((req, res, next) => {
  // Set security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// JSON parsing with size limit (prevent DoS)
app.use(express.json({ limit: '10kb' }));

// URL-encoded parsing with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// =========================================
// INPUT VALIDATION UTILITIES
// =========================================

// Simple validation function for query parameters
const validateQueryParams = (params, rules) => {
  const errors = [];
  const validated = {};

  for (const [key, rule] of Object.entries(rules)) {
    const value = params[key];

    // Check if required
    if (rule.required && (value === undefined || value === '')) {
      errors.push(`${key} is required`);
      continue;
    }

    // Apply default if not provided
    if (value === undefined && rule.default !== undefined) {
      validated[key] = rule.default;
      continue;
    }

    // Skip validation if value is undefined
    if (value === undefined) {
      continue;
    }

    // Type validation
    if (rule.type === 'number') {
      const num = parseInt(value);
      if (isNaN(num)) {
        errors.push(`${key} must be a number`);
        continue;
      }

      // Range validation
      if (rule.min !== undefined && num < rule.min) {
        errors.push(`${key} must be at least ${rule.min}`);
      }
      if (rule.max !== undefined && num > rule.max) {
        errors.push(`${key} must be at most ${rule.max}`);
      }

      validated[key] = num;
    } 
    else if (rule.type === 'string') {
      // Basic sanitization
      const sanitized = String(value)
        .replace(/[<>]/g, '') // Remove angle brackets to prevent XSS
        .trim();

      // Length validation
      if (rule.minLength !== undefined && sanitized.length < rule.minLength) {
        errors.push(`${key} must be at least ${rule.minLength} characters`);
      }
      if (rule.maxLength !== undefined && sanitized.length > rule.maxLength) {
        errors.push(`${key} must be at most ${rule.maxLength} characters`);
      }

      // Allowed values validation
      if (rule.allowed && !rule.allowed.includes(sanitized)) {
        errors.push(`${key} must be one of: ${rule.allowed.join(', ')}`);
      }

      validated[key] = sanitized;
    }
    else if (rule.type === 'boolean') {
      validated[key] = value === 'true' || value === '1';
    }
  }

  return { errors, validated };
};

// =========================================
// ROUTES WITH ERROR HANDLING & VALIDATION
// =========================================

// Health endpoint with error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: requiredConfig.NODE_ENV
    });
  } catch (error) {
    console.error('Health endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Unable to process health check'
    });
  }
});

// Users endpoint with comprehensive validation and error handling
app.get('/users', (req, res) => {
  try {
    // Define validation rules
    const validationRules = {
      limit: {
        type: 'number',
        min: 1,
        max: 100,
        default: 10
      },
      offset: {
        type: 'number',
        min: 0,
        default: 0
      },
      sortBy: {
        type: 'string',
        allowed: ['id', 'name', 'email'],
        default: 'id'
      },
      order: {
        type: 'string',
        allowed: ['asc', 'desc'],
        default: 'asc'
      }
    };

    // Validate query parameters
    const { errors, validated } = validateQueryParams(req.query, validationRules);

    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'Invalid query parameters',
        details: errors
      });
    }

    // Mock database response (in real app, this would be a DB query)
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply sorting based on validated parameters
    const sortedUsers = [...mockUsers].sort((a, b) => {
      const aValue = a[validated.sortBy];
      const bValue = b[validated.sortBy];

      if (validated.order === 'asc') {
        return aValue > bValue ? 1 : -1;
      } else {
        return aValue < bValue ? 1 : -1;
      }
    });

    // Apply pagination
    const start = validated.offset;
    const end = start + validated.limit;
    const paginatedUsers = sortedUsers.slice(start, end);

    // Successful response
    res.json({
      users: paginatedUsers,
      pagination: {
        total: mockUsers.length,
        limit: validated.limit,
        offset: validated.offset,
        hasMore: end < mockUsers.length
      }
    });

  } catch (error) {
    // Log error for monitoring
    console.error('Users endpoint error:', {
      error: error.message,
      stack: requiredConfig.NODE_ENV === 'development' ? error.stack : undefined,
      query: req.query,
      timestamp: new Date().toISOString()
    });

    // Return appropriate error response
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to process request'
    });
  }
});

// =========================================
// ERROR HANDLING MIDDLEWARE
// =========================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled application error:', {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.originalUrl,
    error: error.message,
    stack: requiredConfig.NODE_ENV === 'development' ? error.stack : undefined
  });

  res.status(500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred'
  });
});

// =========================================
// SERVER STARTUP
// =========================================

const server = app.listen(requiredConfig.PORT, () => {
  console.log(`Server running on port ${requiredConfig.PORT}`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Starting graceful shutdown...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Starting graceful shutdown...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

module.exports = app;

