// Enhanced Express application with security best practices
// This version includes comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const morgan = require('morgan');
const { body, param, validationResult } = require('express-validator');

const app = express();

// Security Recommendation 1: Use Helmet.js for security headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        },
    },
    hsts: {
        maxAge: 63072000, // 2 years in seconds
        includeSubDomains: true,
        preload: true
    }
}));

// Security Recommendation 2: Configure CORS properly
app.use(cors({
    origin: process.env.NODE_ENV === 'production' ? [/\.example\.com$/] : '*',
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    maxAge: 86400 // 24 hours
}));

// Security Recommendation 3: Rate limiting to prevent DoS attacks
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: {
        error: 'Too many requests, please try again later.'
    },
    standardHeaders: true,
    legacyHeaders: false
});
app.use(limiter);

// Security Recommendation 4: Request compression
app.use(compression());

// Security Recommendation 5: Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Security Recommendation 6: Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security Recommendation 7: Input validation middleware
const validateInput = (validations) => {
    return async (req, res, next) => {
        await Promise.all(validations.map(validation => validation.run(req)));

        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            return res.status(400).json({
                error: 'Validation failed',
                details: errors.array().map(err => ({
                    param: err.param,
                    msg: err.msg,
                    value: err.value
                }))
            });
        }
        next();
    };
};

// Health endpoint with validation
app.get('/health', (req, res) => {
    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        version: process.env.npm_package_version || '1.0.0',
        environment: process.env.NODE_ENV || 'development'
    });
});

// Users endpoint with validation
app.get('/users', 
    validateInput([
        body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
        body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
        body('search').optional().isString().trim().escape().withMessage('Search must be a string'),
    ]),
    async (req, res) => {
        try {
            // Simulate database access with error handling
            const users = [
                { id: 1, name: 'Alice', email: 'alice@example.com' },
                { id: 2, name: 'Bob', email: 'bob@example.com' },
            ];

            // Apply pagination/filtering based on validated inputs
            let filteredUsers = users;

            if (req.body.search) {
                const searchTerm = req.body.search.toLowerCase();
                filteredUsers = filteredUsers.filter(user => 
                    user.name.toLowerCase().includes(searchTerm) ||
                    user.email.toLowerCase().includes(searchTerm)
                );
            }

            res.json({
                data: filteredUsers,
                count: filteredUsers.length,
                limit: req.body.limit || 10,
                page: req.body.page || 1
            });
        } catch (error) {
            // Log error for monitoring
            console.error('Error fetching users:', error);
            res.status(500).json({
                error: 'Internal server error',
                message: process.env.NODE_ENV === 'production' 
                    ? 'An unexpected error occurred' 
                    : error.message
            });
        }
    }
);

// Security Recommendation 8: Add user endpoint with param validation
app.get('/users/:id',
    validateInput([
        param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
    ]),
    async (req, res) => {
        try {
            const userId = parseInt(req.params.id);
            const users = [
                { id: 1, name: 'Alice', email: 'alice@example.com' },
                { id: 2, name: 'Bob', email: 'bob@example.com' },
            ];

            const user = users.find(u => u.id === userId);

            if (!user) {
                return res.status(404).json({
                    error: 'User not found',
                    message: `User with ID ${userId} does not exist`
                });
            }

            res.json({ data: user });
        } catch (error) {
            console.error(`Error fetching user ${req.params.id}:`, error);
            res.status(500).json({
                error: 'Internal server error',
                message: process.env.NODE_ENV === 'production' 
                    ? 'An unexpected error occurred' 
                    : error.message
            });
        }
    }
);

// Security Recommendation 9: Create user endpoint with comprehensive validation
app.post('/users',
    validateInput([
        body('name').trim().isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
            .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),
        body('email').trim().isEmail().normalizeEmail().withMessage('Valid email is required'),
        body('age').optional().isInt({ min: 0, max: 150 }).withMessage('Age must be between 0 and 150'),
    ]),
    async (req, res) => {
        try {
            // In a real application, you would save to database here
            const newUser = {
                id: 3,
                name: req.body.name,
                email: req.body.email,
                age: req.body.age || null,
                createdAt: new Date().toISOString()
            };

            res.status(201).json({
                message: 'User created successfully',
                data: newUser
            });
        } catch (error) {
            console.error('Error creating user:', error);
            res.status(500).json({
                error: 'Internal server error',
                message: process.env.NODE_ENV === 'production' 
                    ? 'An unexpected error occurred' 
                    : error.message
            });
        }
    }
);

// Security Recommendation 10: Error handling middleware
app.use((req, res, next) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Cannot ${req.method} ${req.url}`
    });
});

app.use((error, req, res, next) => {
    console.error('Unhandled error:', error);

    // Determine appropriate status code
    const statusCode = error.status || error.statusCode || 500;

    // Prepare error response
    const errorResponse = {
        error: error.name || 'Internal Server Error',
        message: process.env.NODE_ENV === 'production' 
            ? 'An unexpected error occurred' 
            : error.message
    };

    // Include stack trace in development
    if (process.env.NODE_ENV !== 'production' && error.stack) {
        errorResponse.stack = error.stack.split('\n');
    }

    res.status(statusCode).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Security Recommendation 11: Graceful shutdown handling
process.on('SIGTERM', () => {
    console.log('SIGTERM signal received: closing HTTP server');
    server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('SIGINT signal received: closing HTTP server');
    server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
    });
});

// Security Recommendation 12: Unhandled rejection handling
process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

// Security Test Suite for the Improved Express Application
// Tests various security features and error handling scenarios

const request = require('supertest');
const app = require('./app_improved');

describe('Security Features Test Suite', () => {
    // Test 1: Basic health endpoint
    test('Health endpoint returns expected response', async () => {
        const response = await request(app).get('/health');
        expect(response.status).toBe(200);
        expect(response.body).toHaveProperty('status', 'ok');
        expect(response.body).toHaveProperty('timestamp');
        expect(response.body).toHaveProperty('environment');
    });

    // Test 2: Security headers
    test('Security headers are present', async () => {
        const response = await request(app).get('/health');

        // Check for Helmet.js headers
        expect(response.headers['x-content-type-options']).toBe('nosniff');
        expect(response.headers['x-frame-options']).toBe('SAMEORIGIN');
        expect(response.headers['x-xss-protection']).toBe('1; mode=block');
        expect(response.headers['strict-transport-security']).toBeDefined();
    });

    // Test 3: Valid user creation
    test('Valid user creation succeeds', async () => {
        const validUser = {
            name: 'Test User',
            email: 'test@example.com'
        };

        const response = await request(app)
            .post('/users')
            .send(validUser);

        expect(response.status).toBe(201);
        expect(response.body.data).toHaveProperty('name', 'Test User');
        expect(response.body.data).toHaveProperty('email', 'test@example.com');
        expect(response.body.data).toHaveProperty('id');
    });

    // Test 4: Invalid user name validation
    test('Invalid user name fails validation', async () => {
        const invalidUser = {
            name: 'A', // Too short
            email: 'test@example.com'
        };

        const response = await request(app)
            .post('/users')
            .send(invalidUser);

        expect(response.status).toBe(400);
        expect(response.body).toHaveProperty('error', 'Validation failed');
        expect(response.body.details[0]).toHaveProperty('param', 'name');
        expect(response.body.details[0].msg).toContain('Name must be between');
    });

    // Test 5: Invalid email validation
    test('Invalid email fails validation', async () => {
        const invalidUser = {
            name: 'Test User',
            email: 'not-an-email'
        };

        const response = await request(app)
            .post('/users')
            .send(invalidUser);

        expect(response.status).toBe(400);
        expect(response.body.details[0]).toHaveProperty('param', 'email');
        expect(response.body.details[0].msg).toContain('Valid email is required');
    });

    // Test 6: XSS payload prevention
    test('XSS payload in name field is sanitized', async () => {
        const xssUser = {
            name: '<script>alert(\'xss\')</script>',
            email: 'test@example.com'
        };

        const response = await request(app)
            .post('/users')
            .send(xssUser);

        expect(response.status).toBe(400); // Should fail validation
        expect(response.body.details[0].msg).toContain('Name can only contain letters and spaces');
    });

    // Test 7: SQL injection attempt
    test('SQL injection in search parameter', async () => {
        const response = await request(app)
            .get('/users')
            .send({
                search: `' OR '1'='1`
            });

        // Should either return empty results or fail validation
        expect(response.status).toBe(200);
        expect(response.body.data).toBeInstanceOf(Array);
    });

    // Test 8: Invalid user ID parameter
    test('Invalid user ID parameter fails validation', async () => {
        const response = await request(app).get('/users/abc');
        expect(response.status).toBe(400);
        expect(response.body.details[0]).toHaveProperty('param', 'id');
        expect(response.body.details[0].msg).toContain('User ID must be a positive integer');
    });

    // Test 9: Non-existent user ID
    test('Non-existent user returns 404', async () => {
        const response = await request(app).get('/users/999');
        expect(response.status).toBe(404);
        expect(response.body).toHaveProperty('error', 'User not found');
    });

    // Test 10: Rate limiting (simulated)
    test('Excessive requests might be rate limited', async () => {
        // Note: This test might fail if run too many times
        // In real scenarios, test with multiple requests quickly
        const response = await request(app).get('/health');
        expect(response.status).toBe(200);
    });

    // Test 11: CORS headers
    test('CORS headers are present', async () => {
        const response = await request(app)
            .get('/health')
            .set('Origin', 'http://example.com');

        expect(response.headers['access-control-allow-origin']).toBeDefined();
        expect(response.headers['access-control-allow-methods']).toBeDefined();
    });

    // Test 12: 404 handling
    test('Non-existent endpoint returns 404', async () => {
        const response = await request(app).get('/non-existent');
        expect(response.status).toBe(404);
        expect(response.body).toHaveProperty('error', 'Not Found');
    });

    // Test 13: Large request body prevention
    test('Oversized request body limit', async () => {
        const largeData = { data: 'x'.repeat(20000) }; // 20KB, exceeding 10KB limit

        const response = await request(app)
            .post('/users')
            .send(largeData);

        // Express should reject or truncate the request
        expect(response.status).not.toBe(500);
    });

    // Test 14: Invalid JSON parsing
    test('Malformed JSON request', async () => {
        const response = await request(app)
            .post('/users')
            .set('Content-Type', 'application/json')
            .send('{invalid json');

        expect(response.status).toBe(400);
    });

    // Test 15: Valid age parameter
    test('Valid age parameter accepted', async () => {
        const userWithAge = {
            name: 'Age Test',
            email: 'age@example.com',
            age: 25
        };

        const response = await request(app)
