            name: 'Invalid Age',
            email: 'invalid@example.com',
            age: -5
        };

        const response = await request(app)
            .post('/users')
            .send(invalidAgeUser);

        expect(response.status).toBe(400);
        expect(response.body.details[0].msg).toContain('Age must be between 0 and 150');
    });

    // Test 17: Special characters in name
    test('Special characters in name rejected', async () => {
        const specialNameUser = {
            name: 'Test123@#$',
            email: 'special@example.com'
        };

        const response = await request(app)
            .post('/users')
