app.get('/health', 
  (req, res) => {
    try {
      // Log health check
      logger.info('Health check endpoint accessed', { ip: req.ip, timestamp: new Date() });

      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        memoryUsage: process.memoryUsage()
      });
