// Secure Express application with improved error handling and input validation
// Security best practices implementation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================
// Security Middleware
// ============================================

// 1. Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// 3. CORS configuration (restrict to trusted origins)
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com', 'https://api.yourdomain.com']
    : 'http://localhost:3000',
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// Custom Error Handling Middleware
// ============================================

// Custom error class for API errors
class APIError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Global error handling middleware
const errorHandler = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  if (process.env.NODE_ENV === 'development') {
    res.status(err.statusCode).json({
      status: err.status,
      error: err,
      message: err.message,
      stack: err.stack
    });
  } else {
    // Production mode: don't leak error details
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });
  }
};

// Async controller wrapper to catch async errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================
// Input Validation Middleware
// ============================================

const validate = (validations) => {
  return async (req, res, next) => {
    for (let validation of validations) {
      const result = await validation.run(req);
      if (result.errors.length) break;
    }

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    res.status(400).json({
      status: 'fail',
      errors: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value
      }))
    });
  };
};

// ============================================
// Routes with Input Validation
// ============================================

// 1. Health check endpoint with validation
app.get('/health', 
  validate([
    query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
  ]),
  asyncHandler(async (req, res) => {
    try {
      const { detailed } = req.query;

      const healthData = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime()
      };

      if (detailed === 'true') {
        healthData.memoryUsage = process.memoryUsage();
        healthData.cpuUsage = process.cpuUsage();
        healthData.nodeVersion = process.version;
      }

      res.json(healthData);
    } catch (error) {
      throw new APIError('Health check failed', 500);
    }
  })
);

// 2. Users endpoint with input validation and sanitization
app.get('/users',
  validate([
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('offset must be a non-negative integer'),
    query('sortBy').optional().isIn(['id', 'name', 'email']).withMessage('sortBy must be one of: id, name, email'),
    query('sortOrder').optional().isIn(['asc', 'desc']).withMessage('sortOrder must be asc or desc')
  ]),
  asyncHandler(async (req, res) => {
    try {
      const { limit = 10, offset = 0, sortBy = 'id', sortOrder = 'asc' } = req.query;

      // Mock user data (in real app, fetch from database with proper sanitization)
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Sort users based on query params
      users.sort((a, b) => {
        if (sortOrder === 'asc') {
          return a[sortBy] > b[sortBy] ? 1 : -1;
        } else {
          return a[sortBy] < b[sortBy] ? 1 : -1;
        }
      });

      // Apply pagination
      const paginatedUsers = users.slice(parseInt(offset), parseInt(offset) + parseInt(limit));

      res.json({
        data: paginatedUsers,
        pagination: {
          total: users.length,
          limit: parseInt(limit),
          offset: parseInt(offset),
          hasMore: parseInt(offset) + parseInt(limit) < users.length
        }
      });
    } catch (error) {
      throw new APIError('Failed to fetch users', 500);
    }
  })
);

// 3. User by ID endpoint with parameter validation and sanitization
app.get('/users/:id',
  validate([
    query('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
  ]),
  asyncHandler(async (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Validate ID is a number
      if (isNaN(userId) || userId <= 0) {
        throw new APIError('Invalid user ID', 400);
      }

      // Mock user lookup (in real app, query database with parameterized queries)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        throw new APIError('User not found', 404);
      }

      // Sanitize response data (remove sensitive info if needed)
      const sanitizedUser = {
        id: user.id,
        name: user.name,
        email: user.email
        // Don't include sensitive fields like password hashes
      };

      res.json({
        status: 'success',
        data: sanitizedUser
      });
    } catch (error) {
      if (error instanceof APIError) {
        throw error;
      }
      throw new APIError('Failed to fetch user', 500);
    }
  })
);

// 4. 404 handler for undefined routes
app.all('*', (req, res, next) => {
  throw new APIError(`Can't find ${req.originalUrl} on this server!`, 404);
});

// ============================================
// Apply Global Error Handler
// ============================================

app.use(errorHandler);

// ============================================
// Server Configuration
// ============================================

const PORT = process.env.PORT || 3000;

// Graceful shutdown handling
const server = app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('👋 SIGTERM RECEIVED. Shutting down gracefully');
  server.close(() => {
    console.log('💥 Process terminated!');
  });
});

module.exports = app;

