// Users endpoint with query parameter validation
app.get('/users', 
    [
        // Validate query parameters
        body('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
        body('offset').optional().isInt({ min: 0 }).toInt(),
        body('search').optional().isString().trim().escape()
    ],
    (req, res, next) => {
        // Check validation results
        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            const validationError = new AppError('Validation failed', 400);
            validationError.errors = errors.array();
            return next(validationError);
        }

        try {
            // Example with mock data - in real app would come from DB
            const users = [
                { 
                    id: 1, 
                    name: 'Alice', 
                    email: 'alice@example.com',
                    role: 'user'
                },
                { 
                    id: 2, 
                    name: 'Bob', 
                    email: 'bob@example.com',
                    role: 'admin'
                },
            ];

            // Filter sensitive data based on user role (example)
            const safeUsers = users.map(user => ({
                id: user.id,
                name: user.name,
                // Don't expose email to unauthorized users in real app
                email: process.env.NODE_ENV === 'development' ? user.email : 'hidden'
            }));

            res.json({
                status: 'success',
                data: safeUsers,
                count: safeUsers.length,
                timestamp: new Date().toISOString()
            });
        } catch (error) {
            next(new AppError('Failed to fetch users', 500));
        }
    }
);

// Example of POST endpoint with validation
app.post('/users',
    [
        body('name').isString().trim().notEmpty().isLength({ min: 2, max: 50 }),
        body('email').isEmail().normalizeEmail(),
        body('age').optional().isInt({ min: 0, max: 150 }).toInt(),
        body('role').optional().isIn(['user', 'admin', 'moderator'])
    ],
    (req, res, next) => {
        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            const validationError = new AppError('Validation failed', 400);
            validationError.errors = errors.array();
            return next(validationError);
        }

        try {
            // In real app: create user in database
            const newUser = {
                id: Date.now(), // temporary ID
                ...req.body,
                createdAt: new Date().toISOString()
            };

            res.status(201).json({
                status: 'success',
                data: newUser,
                message: 'User created successfully'
            });
        } catch (error) {
            next(new AppError('Failed to create user', 500));
        }
    }
);

// ====================
// 5. SERVER SETUP AND SHUTDOWN
// ====================

// Initialize error handler (must be last middleware)
app.use(errorHandler);

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
    console.log(`Server running in ${NODE_ENV} mode on port ${PORT}`);
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);

    server.close(() => {
