// Improved Express application with enhanced error handling and security
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, param, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// Security best practices implementation
// =======================================

// 1. Security Headers using Helmet
app.use(helmet());

// 2. CORS configuration (restrict origins in production)
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : '*',
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// 4. Request logging
app.use(morgan('combined'));

// 5. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payloads
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 6. Input validation middleware
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    res.status(400).json({
      errors: errors.array(),
      message: 'Validation failed'
    });
  };
};

// 7. Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error occurred:', {
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    ip: req.ip
  });

  // Custom error response based on error type
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation Error',
      details: err.message
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid or missing authentication'
    });
  }

  // Default error response
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
    timestamp: new Date().toISOString()
  });
};

// 8. Check for required environment variables
const requiredEnvVars = ['NODE_ENV'];
if (process.env.NODE_ENV === 'production') {
  requiredEnvVars.push('DATABASE_URL', 'SESSION_SECRET');
}

const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);
if (missingEnvVars.length > 0) {
  console.error('Missing required environment variables:', missingEnvVars);
  process.exit(1);
}

// Health check endpoint with input validation
app.get('/health', validate([
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
]), (req, res) => {
  try {
    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    if (req.query.detailed === 'true') {
      healthData.details = {
        node: process.version,
        platform: process.platform,
        environment: process.env.NODE_ENV || 'development'
      };
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check failed:', error);
    res.status(500).json({ 
      status: 'unhealthy', 
      error: 'Internal server error during health check',
      timestamp: new Date().toISOString()
    });
  }
});

// Enhanced users endpoint with validation and error handling
app.get('/users', validate([
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('offset must be a positive integer')
]), async (req, res, next) => {
  try {
    const { limit = 10, offset = 0 } = req.query;

    // Simulate database query with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: new Date().toISOString() },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: new Date().toISOString() },
    ];

    // Apply pagination (in real app, this would be in database query)
    const paginatedUsers = users.slice(offset, offset + parseInt(limit));

    // Sanitize output (remove sensitive data if needed)
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      // Don't include email in response for this example
      // email: user.email
    }));

    res.json({
      data: sanitizedUsers,
      meta: {
        total: users.length,
        limit: parseInt(limit),
        offset: parseInt(offset),
        page: Math.floor(offset / limit) + 1
      }
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    next(error); // Pass to error handler
  }
});

// New secure user creation endpoint with comprehensive validation
app.post('/users', validate([
  body('name')
    .notEmpty().withMessage('Name is required')
    .trim()
    .escape()
    .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s\-']+$/).withMessage('Name can only contain letters, spaces, hyphens, and apostrophes'),
  body('email')
    .notEmpty().withMessage('Email is required')
    .trim()
    .normalizeEmail()
    .isEmail().withMessage('Valid email is required')
    .isLength({ max: 254 }).withMessage('Email too long'),
  body('age')
    .optional()
    .isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120')
]), async (req, res, next) => {
  try {
    const { name, email, age } = req.body;

    // Additional business logic validation
    if (email && email.includes('example.com')) {
      throw new Error('example.com emails are not allowed');
    }

    // In real app, this would save to database
    const newUser = {
      id: Date.now(), // In real app, use UUID or database-generated ID
      name,
      email,
      age: age || null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    // Don't return the entire object in production
    const responseUser = {
      id: newUser.id,
      name: newUser.name,
      createdAt: newUser.createdAt
    };

    res.status(201).json({
      message: 'User created successfully',
      data: responseUser
    });

  } catch (error) {
    console.error('Error creating user:', error);
    next(error);
  }
});

// Specific user endpoint with parameter validation
app.get('/users/:id', validate([
  param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
]), async (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // In real app, fetch user from database
    // This is just an example
    const user = { id: userId, name: 'Sample User', email: 'user@example.com' };

    if (!user) {
      const error = new Error('User not found');
      error.status = 404;
      throw error;
    }

    res.json({
      data: {
        id: user.id,
        name: user.name
        // Don't include sensitive data like email
      }
    });

  } catch (error) {
    next(error);
  }
});

// Add the error handler middleware (must be last)
app.use(errorHandler);

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.url}`,
    timestamp: new Date().toISOString()
  });
});

// Graceful shutdown handling
const gracefulShutdown = () => {
  console.log('Received shutdown signal. Closing server gracefully...');

  server.close((err) => {
    if (err) {
      console.error('Error during graceful shutdown:', err);
      process.exit(1);
    }

    console.log('Server closed. Exiting process.');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Handle termination signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Get port from environment variable with fallback
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Start server
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = { app, server };

// Test script to demonstrate security improvements
const axios = require('axios');

const BASE_URL = 'http://localhost:3000';

async function testSecurityFeatures() {
  console.log('=== Testing Security Features ===\n');

  try {
    // Test 1: Normal health check
    console.log('1. Testing normal health check...');
    const healthResponse = await axios.get(`${BASE_URL}/health`);
    console.log(`   Status: ${healthResponse.status}`);
    console.log(`   Response:`, JSON.stringify(healthResponse.data, null, 2));
    console.log();

    // Test 2: Health check with query parameter (should succeed)
    console.log('2. Testing health check with detailed=true...');
    const detailedHealth = await axios.get(`${BASE_URL}/health?detailed=true`);
    console.log(`   Status: ${detailedHealth.status}`);
    console.log(`   Has details: ${!!detailedHealth.data.details}`);
    console.log();

    // Test 3: Health check with invalid parameter (should fail validation)
    console.log('3. Testing health check with invalid parameter (detailed=invalid)...');
    try {
      const invalidHealth = await axios.get(`${BASE_URL}/health?detailed=invalid`);
      console.log(`   Unexpected success - this should have failed validation`);
    } catch (error) {
      console.log(`   Expected validation error: ${error.response.status}`);
      console.log(`   Error response:`, JSON.stringify(error.response.data, null, 2));
    }
    console.log();

    // Test 4: Users endpoint with pagination
    console.log('4. Testing users endpoint with pagination...');
    const usersResponse = await axios.get(`${BASE_URL}/users?limit=1&offset=0`);
    console.log(`   Status: ${usersResponse.status}`);
    console.log(`   Number of users: ${usersResponse.data.data.length}`);
    console.log(`   Meta data included: ${!!usersResponse.data.meta}`);
    console.log();

    // Test 5: Users endpoint with invalid limit (should fail validation)
    console.log('5. Testing users endpoint with invalid limit (limit=0)...');
    try {
      const invalidLimit = await axios.get(`${BASE_URL}/users?limit=0`);
      console.log(`   Unexpected success - this should have failed validation`);
    } catch (error) {
      console.log(`   Expected validation error: ${error.response.status}`);
      console.log(`   Error message: ${error.response.data.message}`);
    }
    console.log();

    // Test 6: Create user with validation
    console.log('6. Testing user creation with valid data...');
    const createUser = await axios.post(`${BASE_URL}/users`, {
      name: 'John Doe',
      email: 'john.doe@example.com',
      age: 30
    });
    console.log(`   Status: ${createUser.status}`);
    console.log(`   User created with ID: ${createUser.data.data.id}`);
    console.log();

    // Test 7: Create user with invalid email (should fail validation)
    console.log('7. Testing user creation with invalid email...');
    try {
      const invalidUser = await axios.post(`${BASE_URL}/users`, {
        name: 'Test User',
        email: 'not-an-email'
      });
      console.log(`   Unexpected success - this should have failed validation`);
    } catch (error) {
      console.log(`   Expected validation error: ${error.response.status}`);
      console.log(`   Error type: ${error.response.data.error}`);
    }
    console.log();

    // Test 8: Test specific user endpoint
    console.log('8. Testing specific user endpoint...');
    try {
      const specificUser = await axios.get(`${BASE_URL}/users/1`);
      console.log(`   Status: ${specificUser.status}`);
      console.log(`   User retrieved: ${specificUser.data.data.name}`);
    } catch (error) {
      console.log(`   Error: ${error.message}`);
    }
    console.log();

    // Test 9: Test 404 handler
    console.log('9. Testing 404 for undefined route...');
    try {
      const notFound = await axios.get(`${BASE_URL}/undefined-route`);
      console.log(`   Unexpected success - this should return 404`);
    } catch (error) {
      console.log(`   Expected 404 error: ${error.response.status}`);
      console.log(`   Error message: ${error.response.data.message}`);
    }
    console.log();

    // Test 10: Test response sanitization
    console.log('10. Checking user response sanitization...');
    const checkUsers = await axios.get(`${BASE_URL}/users`);
    const firstUser = checkUsers.data.data[0];
    console.log(`   User object keys: ${Object.keys(firstUser).join(', ')}`);
    console.log(`   Email exposed: ${'email' in firstUser}`);
    console.log(`   ✅ Response is properly sanitized`);
    console.log();

    console.log('=== Security Tests Complete ===');
    console.log('\nSummary:');
    console.log('- Input validation: ✓ Working');
    console.log('- Error handling: ✓ Working');
    console.log('- Response sanitization: ✓ Working');
    console.log('- Structured responses: ✓ Working');

  } catch (error) {
    console.error('Test error:', error.message);
    if (error.response) {
      console.error('Response:', error.response.data);
    }
  }
}

// Note: Install axios first if testing: npm install axios
if (require.main === module) {
  console.log('Starting security tests...');
  console.log('Make sure the server is running first!');
  console.log(`Server should be at: ${BASE_URL}\n`);
  testSecurityFeatures();
}

module.exports = { testSecurityFeatures };

