// Enhanced Express application with error handling and input validation
const express = require('express');

const app = express();

// Basic security middlewares
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Server Error:', {
    message: err.message,
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    ip: req.ip
  });

  // Don't expose stack traces in production
  const errorResponse = {
    error: 'Internal Server Error',
    timestamp: new Date().toISOString()
  };

  // Provide validation errors to client
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation Error',
      message: err.message,
      details: err.details
    });
  }

  res.status(500).json(errorResponse);
};

// Input validation helper
const validateInput = (rules) => {
  return (req, res, next) => {
    const errors = [];

    // Check query parameters
    if (rules.query) {
      for (const [param, validator] of Object.entries(rules.query)) {
        if (req.query[param] !== undefined) {
          const result = validator(req.query[param]);
          if (result !== true) {
            errors.push(`Query parameter "${param}": ${result}`);
          }
        }
      }
    }

    // Check body parameters
    if (rules.body) {
      for (const [param, validator] of Object.entries(rules.body)) {
        if (req.body[param] !== undefined) {
          const result = validator(req.body[param]);
          if (result !== true) {
            errors.push(`Body parameter "${param}": ${result}`);
          }
        }
      }
    }

    if (errors.length > 0) {
      const error = new Error('Input validation failed');
      error.name = 'ValidationError';
      error.details = errors;
      return next(error);
    }

    next();
  };
};

// Validation functions
const validators = {
  isInt: (min = 1, max = 100) => (value) => {
    const num = parseInt(value, 10);
    if (isNaN(num)) return 'must be a number';
    if (num < min) return `must be at least ${min}`;
    if (num > max) return `must be at most ${max}`;
    return true;
  },

  isBoolean: () => (value) => {
    if (value === 'true' || value === 'false' || value === true || value === false) {
      return true;
    }
    return 'must be true or false';
  },

  isEmail: () => (value) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (emailRegex.test(value)) return true;
    return 'must be a valid email address';
  },

  isString: (min = 1, max = 100) => (value) => {
    if (typeof value !== 'string') return 'must be a string';
    if (value.length < min) return `must be at least ${min} characters`;
    if (value.length > max) return `must be at most ${max} characters`;
    return true;
  }
};

// Health endpoint with input validation
app.get('/health', validateInput({
  query: {
    detailed: validators.isBoolean()
  }
}), (req, res, next) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (req.query.detailed === 'true') {
      healthData.details = {
        memory: process.memoryUsage(),
        node: process.version,
        environment: process.env.NODE_ENV || 'development'
      };
    }

    res.json(healthData);
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation and pagination
app.get('/users', validateInput({
  query: {
    limit: validators.isInt(1, 50),
    offset: validators.isInt(0, 1000)
  }
}), (req, res, next) => {
  try {
    const limit = parseInt(req.query.limit || '10', 10);
    const offset = parseInt(req.query.offset || '0', 10);

    // Simulated user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination (in real app, this would be database-level)
    const paginatedUsers = users.slice(offset, offset + limit);

    // Sanitize response - don't expose emails
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name
    }));

    res.json({
      data: sanitizedUsers,
      meta: {
        total: users.length,
        limit,
        offset,
        page: Math.floor(offset / limit) + 1
      }
    });
  } catch (error) {
    next(error);
  }
});

// New secure endpoint for creating users with comprehensive validation
