// Secure application with comprehensive error handling and input validation
// This version implements security best practices

const express = require('express');
const helmet = require('helmet');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

// Load environment variables
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// =======================
// Security Configuration
// =======================

// 1. Security headers with helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

// 2. Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// ======================
// Request Configuration
// ======================

// 3. Request size limiting to prevent DoS attacks
const requestBodyLimit = process.env.REQUEST_BODY_LIMIT || '10kb';
app.use(express.json({ limit: requestBodyLimit }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: process.env.MAX_URLENCODED_LENGTH || '10kb' 
}));

// ======================
// Rate Limiting
// ======================

// 4. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  message: {
    error: {
      message: 'Too many requests, please try again later',
      status: 429,
      timestamp: new Date().toISOString()
    }
  },
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => {
    // Use IP address for rate limiting
    return req.ip;
  },
});

app.use(limiter);

// ======================
// Logging Middleware
// ======================

// 5. Request logging
if (NODE_ENV === 'development') {
  app.use(morgan('dev'));
} else {
  app.use(morgan('combined'));
}

// Custom request logging with timing
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      url: req.originalUrl,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent')
    });
  });

  next();
});

// ======================
// Validation Middleware
// ======================

// 6. Centralized validation handler
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    const errorResponse = {
      error: {
        message: 'Validation failed',
        status: 400,
        errors: errors.array().map(err => ({
          field: err.path,
          message: err.msg,
          value: err.value
        })),
        timestamp: new Date().toISOString()
      }
    };

    res.status(400).json(errorResponse);
  };
};

// ======================
// Routes with Validation
// ======================

// 7. Health endpoint with validation
app.get('/health', (req, res) => {
  try {
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: NODE_ENV,
      version: process.version
    };

    // Validate health check data
    if (!healthStatus.status || !healthStatus.timestamp) {
      throw new Error('Health check data incomplete');
    }

    res.json(healthStatus);
  } catch (error) {
    // Log the error but return a generic response
    console.error('Health check failed:', error);
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
      timestamp: new Date().toISOString()
    });
  }
});

// 8. Users endpoint with input validation and sanitization
app.get('/users', 
  [
    // Validate and sanitize query parameters
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['name', 'email', 'id'])
      .withMessage('Sort must be one of: name, email, id')
  ],
  validate,
  (req, res) => {
    try {
      const page = req.query.page || 1;
      const limit = req.query.limit || 20;
      const sort = req.query.sort || 'id';

      // Simulated user data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Validate user data (in real app, this would come from database)
      const validatedUsers = users.map(user => {
        if (!user.id || !user.name || !user.email) {
          throw new Error('Invalid user data structure');
        }

        // Sanitize email for response (in real app, use proper sanitization)
        const sanitizedUser = { ...user };
        if (sanitizedUser.email) {
          sanitizedUser.email = sanitizedUser.email.toLowerCase().trim();
        }

        return sanitizedUser;
      });

      res.json({
        users: validatedUsers,
        pagination: {
          page,
          limit,
          total: validatedUsers.length,
          totalPages: Math.ceil(validatedUsers.length / limit)
        },
        sort,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        error: {
          message: 'Failed to fetch users',
          status: 500,
          timestamp: new Date().toISOString()
        }
      });
    }
  }
);

// ======================
// Error Handling
// ======================

// 9. 404 Not Found Handler
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: `Resource not found: ${req.method} ${req.originalUrl}`,
      status: 404,
      timestamp: new Date().toISOString(),
      suggestedAction: 'Check the endpoint URL and HTTP method'
    }
  });
});

// 10. Global Error Handler
app.use((err, req, res, next) => {
  console.error('Unhandled Error:', {
    message: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  const statusCode = err.statusCode || 500;

  const errorResponse = {
    error: {
      message: statusCode === 500 ? 'Internal server error' : err.message,
      status: statusCode,
      timestamp: new Date().toISOString()
    }
  };

  // Include safe error details in development mode only
  if (NODE_ENV === 'development' && err.details) {
    errorResponse.error.details = err.details;
  }

  res.status(statusCode).json(errorResponse);
});

// ======================
// Server Startup
// ======================

app.listen(PORT, () => {
  console.log({
    message: `Server started successfully`,
    port: PORT,
    environment: NODE_ENV,
    timestamp: new Date().toISOString(),
    securityFeatures: [
      'Helmet security headers',
      'Rate limiting',
      'Input validation',
      'Request size limiting',
      'Comprehensive error handling'
    ]
  });
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received: shutting down gracefully');
  process.exit(0);
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you should restart the process
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

